import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Writing entities in batch","description":"","frontmatter":{"title":"Writing entities in batch","covers":{"screens":[],"stories":["US-141","US-036"]}},"headers":[],"relativePath":"usage/entities-batch.md","filePath":"usage/entities-batch.md"}`),a={name:`usage/entities-batch.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="writing-entities-in-batch" tabindex="-1">Writing entities in batch <a class="header-anchor" href="#writing-entities-in-batch" aria-label="Permalink to “Writing entities in batch”">​</a></h1><p>Source systems – a repository scanner, a CMDB export, a script – create and update entities through <code>POST /api/v1/entities/batch</code>. In this version, the caller is a person with the permission <code>entity:write</code> (role <code>enterprise-architect</code>) and a session (see <a href="./../administration/#log-in-for-administration-through-the-api">Log in for administration through the API</a>); service accounts with client credentials follow in a later version.</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/entities/batch&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Agent-Id: repo-scanner&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Agent-Run: 2026-10-16-nightly&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;strategy&quot;: &quot;upsert&quot;, &quot;entities&quot;: [{&quot;name&quot;: &quot;CRM System&quot;, &quot;metatypeId&quot;: &quot;&lt;id&gt;&quot;, &quot;externalId&quot;: &quot;git:org/crm&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;properties&quot;: [{&quot;propertyDefId&quot;: &quot;&lt;id of Status&gt;&quot;, &quot;value&quot;: &quot;active&quot;}]}]}&#39;</span></span></code></pre></div><p><code>GET /metamodel/metatypes</code> returns the IDs of the entity types and their properties.</p><h2 id="how-items-are-written" tabindex="-1">How items are written <a class="header-anchor" href="#how-items-are-written" aria-label="Permalink to “How items are written”">​</a></h2><ul><li><code>externalId</code> identifies an entity from the source system. With the strategy <code>upsert</code>, an unknown ID creates the entity and a known one updates it; <code>create-only</code> and <code>skip-existing</code> behave as named.</li><li>On update, fields and properties missing in the item stay unchanged; an empty value removes a property value. An unchanged item is reported as <code>unchanged</code> and creates no version.</li><li>With <code>atomic=false</code> (default), every item is written on its own and the answer reports a status per item. With <code>atomic=true</code>, all items are written or none (<code>422</code> with the errors per item).</li><li>A request contains at most <code>oea.entities.batch.max-items</code> entities (default and maximum 500) and at most 10 MB.</li><li><code>X-Agent-Id</code> and <code>X-Agent-Run</code> are stored only as informational fields of the audit events.</li></ul><p>Not supported yet: <code>dryRun=true</code>, <code>parentId</code>, <code>lifecycle</code> and properties with restricted visibility (<code>422</code> or an error for the item).</p><p>Every written entity creates a new version with the previous values of the changed fields and the audit event <code>entity.created</code> or <code>entity.updated</code>.</p><h2 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to “Connections”">​</a></h2><p>Connections are entities of a <a href="./../administration/metamodel-editing#connection-types">connection type</a> with one source and one target. Send them in <code>connections</code> of the same batch; they are written after the entities, so that they can name entities of the batch by their external ID:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/entities/batch&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;strategy&quot;: &quot;upsert&quot;, &quot;atomic&quot;: true,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;entities&quot;: [{&quot;name&quot;: &quot;CRM&quot;, &quot;metatypeId&quot;: &quot;&lt;id&gt;&quot;, &quot;externalId&quot;: &quot;cmdb:crm&quot;},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               {&quot;name&quot;: &quot;ERP&quot;, &quot;metatypeId&quot;: &quot;&lt;id&gt;&quot;, &quot;externalId&quot;: &quot;cmdb:erp&quot;}],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;connections&quot;: [{&quot;connectionMetatypeId&quot;: &quot;&lt;id of Data Flow&gt;&quot;, &quot;externalId&quot;: &quot;flow:crm-erp&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                   &quot;sourceExternalId&quot;: &quot;cmdb:crm&quot;, &quot;targetExternalId&quot;: &quot;cmdb:erp&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                   &quot;properties&quot;: [{&quot;propertyDefId&quot;: &quot;&lt;id of Protocol&gt;&quot;, &quot;value&quot;: &quot;sftp&quot;}]}]}&#39;</span></span></code></pre></div><ul><li>Name the source and the target either by ID (<code>sourceId</code>, <code>targetId</code>) or by external ID (<code>sourceExternalId</code>, <code>targetExternalId</code>), not both. A connection may start or end at another connection if the connection type allows it.</li><li>Without <code>name</code>, a new connection is named &quot;source name → target name&quot;.</li><li>Source and target cannot change. Sending a known connection with another source or target is an error; send it as a new connection instead. Deleting connections follows in a later version.</li><li>Strategies, atomicity and the limit of 500 apply to connections as to entities. The answer reports connections with <code>itemType</code> <code>connection</code> and their index in <code>connections</code>.</li><li>Error codes of a connection: <code>SOURCE_REQUIRED</code>, <code>SOURCE_AMBIGUOUS</code>, <code>SOURCE_NOT_FOUND</code> and <code>SOURCE_NOT_ALLOWED</code> (the same with <code>TARGET_</code>), <code>METATYPE_NOT_CONNECTION</code> and <code>ENDPOINT_CHANGE_NOT_SUPPORTED</code>. An entity of a connection type sent in <code>entities</code> is rejected with <code>METATYPE_IS_CONNECTION</code>.</li></ul><p>A single connection is created with <code>POST /api/v1/connections</code> and the same fields; the answer (<code>201</code>) contains the connection with its source and target. A missing source or target gives <code>404</code>, other errors <code>422</code>.</p><p><code>GET /metamodel/allowed-connections?sourceMetatypeId=…&amp;targetMetatypeId=…</code> tells you in advance which connection types may connect two entity types.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};